{"sql": "SELECT COUNT(DISTINCT customer_id), MAX(txn_count)
FROM (
    SELECT customer_id, COUNT(*) as txn_count
    FROM customer_transactions
    GROUP BY customer_id
)"}

{"sql": "SELECT COUNT(DISTINCT customer_id), MAX(date_span_days)
FROM (
    SELECT customer_id, CAST(MAX(txn_date) - MIN(txn_date) AS INTEGER) as date_span_days
    FROM customer_transactions
    GROUP BY customer_id
)"}

{"sql": "WITH RECURSIVE dates AS (
    SELECT DATE '2020-01-01' as d
    UNION ALL
    SELECT d + INTERVAL '1 day' FROM dates WHERE d < DATE '2020-04-28'
)
SELECT * FROM dates LIMIT 10"}

{"sql": "WITH customer_dates AS (
    SELECT customer_id, MIN(txn_date) as first_date, MAX(txn_date) as last_date
    FROM customer_transactions
    GROUP BY customer_id
),
date_series AS (
    SELECT customer_id, d as date
    FROM customer_dates,
    UNNEST(
        SELECT GENERATE_SERIES(first_date::DATE, last_date::DATE) as d
    )
)
SELECT * FROM date_series WHERE customer_id = 1 LIMIT 20"}
